head.script:
scwin.screenId = "jldstf60016";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        for (let i = 0; i < scwin.tabList.length; i++) {
            if (i == 0) {
                var li = $("<li class='active'>" + scwin.tabList[i].title + "</li>");
            } else {
                var li = $("<li>" + scwin.tabList[i].title + "</li>");
            }
            (function(index) {
                    li.click(function() {
                            $("#tabContainer li").removeClass("active");
                            $(this).addClass("active");
                            scwin.onTabClick(index);
                    });
            })(i);
            $("#tabContainer").append(li);
        }
        scwin.onTabClick(0);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf60016.onpageload' }); }
};

