/**
 * @method
 * @name scwin.onTabClick
 * @author Inswave
 * @date 2026. 09. 29
 * @param tabIndex
 * @returns
 * @hidden N
*/
scwin.onTabClick = function (tabIndex) {
    /* sdd-asis-lifecycle:begin onTabClick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const container = $("#contents");
    container.empty();
    if (tabIndex == 0) {
        container.html(scwin.htmlA);
    } else {
        if (tabIndex == 1) {
            container.html(scwin.htmlB);
        } else {
            if (tabIndex == 2) {
                container.html(scwin.htmlC);
            } else {
                if (tabIndex == 3) {
                    container.html(scwin.htmlD);
                } else {
                    if (tabIndex == 4) {
                        container.html(scwin.htmlE);
                    } else {
                        if (tabIndex == 5) {
                            container.html(scwin.htmlF);
                        } else {
                            if (tabIndex == 6) {
                                container.html(scwin.htmlG);
                            } else {
                                if (tabIndex == 7) {
                                    container.html(scwin.htmlH);
                                } else {
                                    if (tabIndex == 8) {
                                        container.html(scwin.htmlI);
                                    } else {
                                        if (tabIndex == 9) {
                                            container.html(scwin.htmlJ);
                                        } else {
                                            if (tabIndex == 10) {
                                                container.html(scwin.htmlK);
                                            } else {
                                                if (tabIndex == 11) {
                                                    container.html(scwin.htmlL);
                                                } else {
                                                    if (tabIndex == 12) {
                                                        container.html(scwin.htmlM);
                                                    } else {
                                                        if (tabIndex == 13) {
                                                            container.html(scwin.htmlN);
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};
